/**
 * The device's state now. Battery, power and thermal changes
 * are pushed; storage and memory are read on each `status()`.
 */
public struct DeviceStatus: Equatable, Hashable {
    /**
     * 0.0 to 1.0, `None` where unknown (the simulator).
     */
    public var batteryLevel: Float?
    public var batteryState: BatteryState
    public var lowPowerMode: Bool
    public var thermalState: ThermalState
    public var storageTotalBytes: UInt64?
    /**
     * Space available for things the user asked for (iOS
     * "important usage": counts purgeable space).
     */
    public var storageAvailableBytes: UInt64?
    /**
     * How much more memory this app may use before the system
     * ends it (`os_proc_available_memory`); `None` off iOS.
     */
    public var memoryAvailableBytes: UInt64?
    /**
     * Memory this app uses now (physical footprint).
     */
    public var memoryFootprintBytes: UInt64?
    /**
     * Seconds since the device started.
     */
    public var uptimeSeconds: Double
    /**
     * Screen brightness 0.0 to 1.0, `None` off iOS.
     */
    public var screenBrightness: Float?
    /**
     * When the host read this (Unix milliseconds).
     */
    public var observedAtMs: Int64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * 0.0 to 1.0, `None` where unknown (the simulator).
         */batteryLevel: Float?, batteryState: BatteryState, lowPowerMode: Bool, thermalState: ThermalState, storageTotalBytes: UInt64?, 
        /**
         * Space available for things the user asked for (iOS
         * "important usage": counts purgeable space).
         */storageAvailableBytes: UInt64?, 
        /**
         * How much more memory this app may use before the system
         * ends it (`os_proc_available_memory`); `None` off iOS.
         */memoryAvailableBytes: UInt64?, 
        /**
         * Memory this app uses now (physical footprint).
         */memoryFootprintBytes: UInt64?, 
        /**
         * Seconds since the device started.
         */uptimeSeconds: Double, 
        /**
         * Screen brightness 0.0 to 1.0, `None` off iOS.
         */screenBrightness: Float?, 
        /**
         * When the host read this (Unix milliseconds).
         */observedAtMs: Int64) {
        self.batteryLevel = batteryLevel
        self.batteryState = batteryState
        self.lowPowerMode = lowPowerMode
        self.thermalState = thermalState
        self.storageTotalBytes = storageTotalBytes
        self.storageAvailableBytes = storageAvailableBytes
        self.memoryAvailableBytes = memoryAvailableBytes
        self.memoryFootprintBytes = memoryFootprintBytes
        self.uptimeSeconds = uptimeSeconds
        self.screenBrightness = screenBrightness
        self.observedAtMs = observedAtMs
    }

    

    
}

