        let len: Int32 = try readInt(&buf)
        var seq = [NetworkInterface]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeNetworkInterface.read(from: &buf))
        }
        return seq
